package io.github.jtsato.walletservice.infra.database.common.filter;
import com.querydsl.core.types.dsl.BooleanExpression; import io.github.jtsato.walletservice.core.common.exception.FieldViolation; import io.github.jtsato.walletservice.core.common.exception.ValidationException; import io.github.jtsato.walletservice.core.common.filter.*; import java.util.*;
public final class QuerydslFilterMapper { private QuerydslFilterMapper() {} public static Optional<BooleanExpression> toPredicate(FilterExpression expression, QuerydslFilterDefinition definition) { if (expression == null) throw error("expression", "common.querydsl.filter.expression.required", "Filter expression is required."); if (definition == null) throw error("definition", "common.querydsl.filter.definition.required", "Filter definition is required."); return expression.root().map(root -> group(root, definition)); } private static BooleanExpression group(FilterGroup group, QuerydslFilterDefinition definition) { List<BooleanExpression> children = new ArrayList<>(); for (var condition : group.conditions()) children.add(condition(condition, definition)); for (var nested : group.groups()) children.add(group(nested, definition)); var result = children.get(0); for (int index = 1; index < children.size(); index++) result = group.operator() == FilterGroupOperator.AND ? result.and(children.get(index)) : result.or(children.get(index)); return result; } @SuppressWarnings({"rawtypes", "unchecked"}) private static BooleanExpression condition(FilterCondition condition, QuerydslFilterDefinition definition) { var candidate = definition.findField(condition.field()); if (candidate.isEmpty()) throw error(condition.field(), "common.querydsl.filter.field.unsupported", "Unsupported filter field."); var field = candidate.get(); var candidateOperation = ((QuerydslFilterFieldDefinition) field).findOperation(condition.operator()); if (candidateOperation.isEmpty()) throw error(condition.field(), "common.querydsl.filter.operator.not-allowed", "Filter operator is not allowed for this field."); return ((QuerydslFilterFieldDefinition.Operation) candidateOperation.get()).apply(QuerydslFilterValueConverter.convertAll(condition.values(), field.valueType())); } private static ValidationException error(String field, String key, String message) { return new ValidationException(List.of(new FieldViolation(field, key, message))); } }
